{"command":"python3 - << 'PY'
import subprocess, itertools
def run(typ):
    data="00"*512
    r=subprocess.run(["./executable","decode","params","-t",typ,data], capture_output=True, text=True)
    return r.returncode, r.stdout.strip(), r.stderr.strip()

# generate valid types small depth
base=["bool","uint256"]
def gen(depth):
    if depth==0:
        yield from base
    else:
        yield from base
        prev=list(gen(depth-1))
        for a in prev:
            yield f"({a})"
        for a in prev:
            for b in prev:
                yield f"({a},{b})"

uniq=[]
seen=set()
for t in gen(2):
    if t not in seen:
        seen.add(t); uniq.append(t)
fails=[]
oks=[]
for t in uniq:
    rc,out,err=run(t)
    # expected display is t itself (canonical same for these)
    expected_prefix=t+" "
    if rc!=0:
        fails.append((t,err))
    elif not out.startswith(expected_prefix):
        fails.append((t,f"mismatch out={out}"))
    else:
        oks.append(t)
print(f"total {len(uniq)} ok {len(oks)} fail {len(fails)}")
for t,e in fails:
    print(t, "=>", e)
PY"}

