import subprocess, string
def run(typ):
    data="00"*32
    r=subprocess.run(["./executable","decode","params","-t",typ,data], capture_output=True, text=True)
    return r
for c in string.printable.strip():
    r=run(c)
    if r.returncode not in (0,1):
        print(repr(c), r.returncode, r.stderr.strip().splitlines()[:2])
print("done single")
# length2 combos of brackets/parens
chars="()[],ab"
for a in chars:
 for b in chars:
  t=a+b
  r=run(t)
  if r.returncode not in (0,1):
    print(repr(t), r.returncode, r.stderr.strip().splitlines()[:2])
print("done double")
for a in chars:
 for b in chars:
  for cc in chars:
    t=a+b+cc
    r=run(t)
    if r.returncode not in (0,1):
      print(repr(t), r.returncode, r.stderr.strip().splitlines()[:2])
print("done triple")
PY"}

