import subprocess
def enc(typ,val, lenient=False):
    args=["encode","params"]
    if lenient: args.append("-l")
    args+=["-v",typ,val]
    r=subprocess.run(["./executable"]+args,capture_output=True,text=True)
    return r.returncode, r.stdout.strip(), r.stderr.strip()
def show(typ,vals):
    for v in vals:
        print(f"{typ} strict {v!r} => {enc(typ,v,False)}")
