def token_display(tok):
    k=tok[0]
    if k=='address':
        return tok[1].hex()
    if k=='bool':
        return "true" if tok[1] else "false"
    if k in ('uint','int'):
        return f"{tok[1]:x}"
    if k in ('fixedbytes','bytes'):
        return tok[1].hex()
    if k=='string':
        return tok[1]
    if k in ('array','fixedarray'):
        return "[" + ",".join(token_display(x) for x in tok[1]) + "]"
    if k=='tuple':
        return "(" + ",".join(token_display(x) for x in tok[1]) + ")"
    raise AssertionError(k)

def token_is_dynamic(tok):
    k=tok[0]
    if k in ('bytes','string','array'):
        return True
    if k in ('fixedarray','tuple'):
        return any(token_is_dynamic(x) for x in tok[1])
    return False

def token_static_size(tok):
    # encoded byte size when static
    k=tok[0]
    if k in ('address','bool','uint','int'):
        return 32
    if k=='fixedbytes':
        n=len(tok[1])
        return ((n+31)//32)*32
    if k in ('fixedarray','tuple'):
        return sum(token_static_size(x) for x in tok[1])
    raise AssertionError("dynamic token static size")

