    k=tok[0]
    if k=='address':
        return b'\x00'*12 + tok[1]
    if k=='bool':
        return (1 if tok[1] else 0).to_bytes(32,'big')
    if k in ('uint','int'):
        return (tok[1] % (1<<256)).to_bytes(32,'big')
    if k=='fixedbytes':
        return _pad_right(tok[1],32)
    if k in ('fixedarray','tuple'):
        return encode_sequence(tok[1])
    raise AssertionError(k)

def encode_token_tail(tok):
    k=tok[0]
    if k=='bytes':
        b=tok[1]
        return len(b).to_bytes(32,'big') + _pad_right(b,32)
    if k=='string':
        b=tok[1].encode('utf-8')
        return len(b).to_bytes(32,'big') + _pad_right(b,32)
    if k=='array':
        return len(tok[1]).to_bytes(32,'big') + encode_sequence(tok[1])
    if k in ('fixedarray','tuple'):
        return encode_sequence(tok[1])
    raise AssertionError(k)

def encode_sequence(tokens):
    head_size=0
    for t in tokens:
        head_size += 32 if token_is_dynamic(t) else token_static_size(t)
    heads=[]
    tails=[]
    offset=head_size
    for t in tokens:
        if token_is_dynamic(t):
            heads.append(offset.to_bytes(32,'big'))
            tail=encode_token_tail(t)
            tails.append(tail)
            offset+=len(tail)
        else:
            heads.append(encode_token_static(t))
    return b''.join(heads)+b''.join(tails)

def encode_tokens(tokens):
    return encode_sequence(tokens)

# ----------------------- Decoder -----------------------
def _peek(data: bytes, offset: int, length: int):
    # offset/length may be huge python ints
    if offset < 0 or length < 0 or offset+length > len(data):
        raise err_invalid_data()
    return data[offset:offset+length]

def _peek32(data: bytes, offset: int):
    if len(data)==0:
        raise err_empty()
    return _peek(data, offset, 32)

def _as_usize(word: bytes):
    v=int.from_bytes(word,'big')
    if v > 18446744073709551615:
        raise err_invalid_data()
    return v

def _from_utf8_lossy(b: bytes) -> str:
    # Rust String::from_utf8_lossy follows the Unicode Standard's
    # substitution of maximal subpart (same general approach as Python's replace
    # for most inputs, but group invalid sequences properly).
    # Implement using Rust's algorithm based on std Utf8Chunks: iterate valid
    # prefixes and invalid chunks with length determined by the first byte
    # and available continuation bytes (maximal subpart table from Unicode).
    # This implementation uses the WHATWG/Unicode-recommended table via
    # incremental decoding: try to decode one char; on failure determine
    # invalid length as per Rust core::str::utf8_char_width / error_len logic.
    res=[]
    i=0
    n=len(b)
    while i<n:
        first=b[i]
        if first < 0x80:
            res.append(chr(first)); i+=1; continue
        # determine width and validity using Python try for widths
        if 0xC2 <= first <= 0xDF:
            width=2
        elif first==0xE0 or 0xE1 <= first <= 0xEC or 0xEE <= first <= 0xEF or first==0xED:
            width=3
        elif 0xF0 <= first <= 0xF4:
            width=4
        else:
            # invalid leading byte (0x80-0xC1, 0xF5-0xFF)
            res.append('\ufffd'); i+=1; continue
        # gather continuation bytes
        # maximal subpart: check second byte range specially
        if i+1>=n:
            res.append('\ufffd'); break
        second=b[i+1]
        # range restrictions for second byte
        def second_ok():
            if first==0xE0:
                return 0xA0 <= second <= 0xBF
            if first==0xED:
                return 0x80 <= second <= 0x9F
            if first==0xF0:
                return 0x90 <= second <= 0xBF
            if first==0xF4:
                return 0x80 <= second <= 0x8F
            return 0x80 <= second <= 0xBF
        if not second_ok():
            res.append('\ufffd'); i+=1; continue
        if width==2:
            res.append(b[i:i+2].decode('utf-8')); i+=2; continue
        if i+2>=n:
            res.append('\ufffd'); break
        third=b[i+2]
        if not (0x80 <= third <= 0xBF):
            res.append('\ufffd'); i+=2; continue
        if width==3:
            res.append(b[i:i+3].decode('utf-8')); i+=3; continue
        if i+3>=n:
            res.append('\ufffd'); break
        fourth=b[i+3]
        if not (0x80 <= fourth <= 0xBF):
            res.append('\ufffd'); i+=3; continue
        res.append(b[i:i+4].decode('utf-8')); i+=4
    return ''.join(res)

class _Decoder:
    def __init__(self, data):
        self.data=data

    def decode_sequence(self, types, start):
        tokens=[]
        offset=start
        for pt in types:
            tok, taken = self.decode_token(pt, offset, start)
            tokens.append(tok)
            offset += taken
        return tokens, offset-start

    def decode_token(self, pt, offset, base):
        # base is the start of the enclosing sequence (for relative dynamic offsets)
        k=pt[0]
        # Tuple / fixed-array special empty handling (observed): when total
        # data is empty, decoding a (non-empty-size) tuple or fixed array
        # yields the empty-bytes error rather than succeeding with zero-size.
        if k=='tuple':
            if len(self.data)==0:
                raise err_empty()
        if k=='fixedarray':
            if len(self.data)==0 and pt[2]!=0:
                raise err_empty()
        if pt_is_dynamic(pt):
            # read head offset word
            # For dynamic fixed arrays of size 0, the reference reports
            # Invalid data (generic peek) rather than the empty error
            if k=='fixedarray' and pt[2]==0:
                word=_peek(self.data, offset, 32)
            else:
                word=_peek32(self.data, offset)
            rel=_as_usize(word)
            target=base+rel
            tok=self.decode_tail(pt, target)
            return tok, 32
        else:
            return self.decode_static(pt, offset)

    def decode_tail(self, pt, target):
        k=pt[0]
        if k=='bytes':
            length=_as_usize(_peek32(self.data, target))
            b=_peek(self.data, target+32, length)
            return ('bytes', b)
        if k=='string':
            length=_as_usize(_peek32(self.data, target))
            b=_peek(self.data, target+32, length)
            return ('string', _from_utf8_lossy(b))
        if k=='array':
            length=_as_usize(_peek32(self.data, target))
            # sanity guard against absurd allocations: if length is larger
            # than remaining data could possibly allow for non-zero-width
            # elements the per-element decoding will fail quickly; but for
            # zero-width static elements we may loop a long time.  The
            # reference behaves the same way, so simply loop.
            # However, to avoid hanging forever on pathological lengths for
            # zero-sized elements, note that each iteration consumes at
            # least the 'taken' logic of decode_sequence; zero-width fixed
            # bytes still take 32, fixed arrays of size0 take 0 -- in that
            # rare case a huge length would loop in reference too.
            types=[pt[1]]*length if length <= 10000000 else None
            if types is None:
                # fall back to iterative without preallocating huge list of types
                toks=[]
                off=target+32
                for _ in range(length):
                    tok,taken=self.decode_token(pt[1], off, target+32)
                    toks.append(tok); off+=taken
                return ('array', toks)
            toks,_t=self.decode_sequence(types, target+32)
            return ('array', toks)
        if k=='fixedarray':
            types=[pt[1]]*pt[2]
            toks,_t=self.decode_sequence(types, target)
            return ('fixedarray', toks)
        if k=='tuple':
            toks,_t=self.decode_sequence(list(pt[1]), target)
            return ('tuple', toks)
        raise AssertionError(k)

    def decode_static(self, pt, offset):
        k=pt[0]
        if k=='address':
            word=_peek32(self.data, offset)
            return ('address', word[12:32]), 32
        if k=='bool':
            word=_peek32(self.data, offset)
            if any(word[i]!=0 for i in range(31)):
                raise err_invalid_data()
            return ('bool', word[31]==1), 32
        if k=='uint':
            word=_peek32(self.data, offset)
            return ('uint', int.from_bytes(word,'big')), 32
        if k=='int':
            word=_peek32(self.data, offset)
            return ('int', int.from_bytes(word,'big')), 32
        if k=='fixedbytes':
            size=pt[1]
            if size>0 and len(self.data)==0:
                raise err_empty()
            b=_peek(self.data, offset, size)
            return ('fixedbytes', b), 32
        if k=='fixedarray':
            types=[pt[1]]*pt[2]
            toks,taken=self.decode_sequence(types, offset)
            return ('fixedarray', toks), taken
        if k=='tuple':
            toks,taken=self.decode_sequence(list(pt[1]), offset)
            return ('tuple', toks), taken
        raise AssertionError(k)

def decode_params(types, data: bytes):
    dec=_Decoder(data)
    toks,_t=dec.decode_sequence(list(types), 0)
    return toks

