# Tokens
# ('address',bytes20) ('bool',bool) ('uint',int) ('int',int256u)
# ('fixedbytes',bytes) ('bytes',bytes) ('string',str)
# ('array',[..]) ('fixedarray',[..]) ('tuple',[..])
