        k=pt[0]
        if k=='address':
            b=self._hex(clean_0x(value))
            if len(b)!=20:
                raise err_invalid_data()
            return ('address', b)
        if k=='bool':
            if value in ("true","1"):
                return ('bool', True)
            if value in ("false","0"):
                return ('bool', False)
            raise err_invalid_data()
        if k=='string':
            return ('string', value)
        if k=='bytes':
            b=self._hex(clean_0x(value))
            return ('bytes', b)
        if k=='fixedbytes':
            b=self._hex(clean_0x(value))
            if len(b)!=pt[1]:
                raise err_invalid_data()
            return ('fixedbytes', b)
        if k=='uint':
            if self.lenient:
                return ('uint', self._lenient_uint_value(value))
            else:
                b=self._hex(value)
                if len(b)!=32:
                    raise err_invalid_data()
                return ('uint', int.from_bytes(b,'big'))
        if k=='int':
            if self.lenient:
                return ('int', self._lenient_int_value(value))
            else:
                b=self._hex(value)
                if len(b)!=32:
                    raise err_invalid_data()
                return ('int', int.from_bytes(b,'big'))
        if k=='array':
            bits=self._split_array(value)
            toks=[self.tokenize(pt[1], bit) for bit in bits]
            return ('array', toks)
        if k=='fixedarray':
            bits=self._split_array(value)
            toks=[self.tokenize(pt[1], bit) for bit in bits]
            if len(toks)!=pt[2]:
                raise err_invalid_data()
            return ('fixedarray', toks)
        if k=='tuple':
            bits=self._split_tuple(value)
            toks=[]
            for bit, sub in zip(bits, pt[1]):
                toks.append(self.tokenize(sub, bit))
            if len(bits) > len(pt[1]):
                raise err_invalid_data()
            return ('tuple', toks)
        raise AssertionError(k)

    def _split_inner(self, inner, is_tuple=False):
        if inner=="":
            return []
        bits=[]
        depth=0
        start=0
        for i,ch in enumerate(inner):
            if ch=='(' or ch=='[':
                depth+=1
            elif ch==')' or ch==']':
                depth-=1
                if depth<0:
                    raise err_invalid_data()
            elif ch==',' and depth==0:
                bits.append(inner[start:i])
                start=i+1
        if depth==0:
            bits.append(inner[start:])
        else:
            # incomplete final element is dropped (matches reference behaviour
            # for unbalanced nested values)
            pass
        return bits

    def _split_array(self, value):
        if not (value.startswith('[') and value.endswith(']')):
            raise err_invalid_data()
        inner=value[1:-1]
        return self._split_inner(inner)

    def _split_tuple(self, value):
        if not (value.startswith('(') and value.endswith(')')):
            raise err_invalid_data()
        inner=value[1:-1]
        return self._split_inner(inner, is_tuple=True)

