# ---------------------------------------------------------------------------
# JSON parsing (serde_json-like) and Contract loading
# ---------------------------------------------------------------------------
class JNode:
    __slots__=('kind','value','start','end','items','entries','raw')
    def __init__(self,kind,value=None,start=0,end=0,items=None,entries=None,raw=None):
        self.kind=kind; self.value=value; self.start=start; self.end=end
        self.items=items or []; self.entries=entries or []; self.raw=raw

def _serde_position(text, index):
    # serde_json: line is 1-based, column is number of characters since
    # beginning of line up to (and not including?) the given index.  Empirical
    # calibration: col = index - (start-of-line index)
    if index<0: index=0
    prefix=text[:index]
    line=prefix.count('\n')+1
    last=prefix.rfind('\n')
    col=index-last-1 if last>=0 else index
    return line,col

def _serde_msg_at(text, msg, index):
    line,col=_serde_position(text,index)
    return f"{msg} at line {line} column {col}"

class JsonParser:
    def __init__(self,text):
        self.s=text; self.n=len(text); self.i=0
    def err(self,msg,index=None):
        if index is None: index=self.i
        raise SerdeErrorRaw(_serde_msg_at(self.s,msg,index))
    def peek(self):
        return self.s[self.i] if self.i<self.n else None
    def skip_ws(self):
        while self.i<self.n and self.s[self.i] in ' \t\n\r':
            self.i+=1
    def parse_value(self):
        self.skip_ws()
        if self.i>=self.n:
            self.err("EOF while parsing a value", self.i)
        c=self.s[self.i]
        if c=='{':
            return self.parse_object()
        if c=='[':
            return self.parse_array()
        if c=='"':
            st=self.i
            val=self.parse_string()
            return JNode('string',val,st,self.i)
        if c=='t' or c=='f' or c=='n':
            return self.parse_literal()
        if c=='-' or c.isdigit():
            return self.parse_number()
        # expected value: serde consumes/peeks the offending char
        self.i+=1
        self.err("expected value", self.i)
    def parse_literal(self):
        st=self.i
        c=self.s[self.i]
        lit={'t':"true",'f':"false",'n':"null"}[c]
        # serde checks expected ident: reads one by one
        for j,exp in enumerate(lit):
            if self.i>=self.n:
                self.err("EOF while parsing a value", self.i)
            if self.s[self.i]!=exp:
                self.i+=1
                self.err("expected ident", self.i)
            self.i+=1
        if lit=="true": return JNode('bool',True,st,self.i)
        if lit=="false": return JNode('bool',False,st,self.i)
        return JNode('null',None,st,self.i)
    def parse_number(self):
        st=self.i
        # grammar mimic serde_json enough for typical malformed numbers
        if self.i<self.n and self.s[self.i]=='-':
            self.i+=1
            if self.i>=self.n:
                self.err("EOF while parsing a value", self.i)
        # int part
        if self.i>=self.n or not self.s[self.i].isdigit():
            self.i+=1
            self.err("invalid number", self.i)
        if self.s[self.i]=='0':
            self.i+=1
        else:
            while self.i<self.n and self.s[self.i].isdigit():
                self.i+=1
        is_float=False
        if self.i<self.n and self.s[self.i]=='.':
            is_float=True
            self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit():
                # serde: invalid number at position after dot?
                if self.i<self.n: self.i+=1
                self.err("invalid number", self.i)
            while self.i<self.n and self.s[self.i].isdigit():
                self.i+=1
        if self.i<self.n and self.s[self.i] in 'eE':
            is_float=True
            self.i+=1
            if self.i<self.n and self.s[self.i] in '+-':
                self.i+=1
            if self.i>=self.n or not self.s[self.i].isdigit():
                if self.i<self.n: self.i+=1
                self.err("invalid number", self.i)
            while self.i<self.n and self.s[self.i].isdigit():
                self.i+=1
        raw=self.s[st:self.i]
        if is_float:
            try: v=float(raw)
            except Exception: v=0.0
            return JNode('float',v,st,self.i,raw=raw)
        else:
            try: v=int(raw)
            except Exception: v=0
            # serde_json classifies numbers that do not fit in i64/u64 as f64
            if v < -(1<<63) or v > (1<<64)-1:
                return JNode('float',float(raw),st,self.i,raw=raw)
            return JNode('int',v,st,self.i,raw=raw)
    def parse_string(self):
        # assumes current char is '"'
        assert self.s[self.i]=='"'
        self.i+=1
        out=[]
        while True:
            if self.i>=self.n:
                self.err("EOF while parsing a string", self.i)
            c=self.s[self.i]
            if c=='"':
                self.i+=1
                return ''.join(out)
            if c=='\\':
                self.i+=1
                if self.i>=self.n:
                    self.err("EOF while parsing a string", self.i)
                e=self.s[self.i]; self.i+=1
                mp={'"':'"','\\':'\\\\','/':'/','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t'}
                # note \\ handling below corrected
                if e=='"': out.append('"')
                elif e=='\\': out.append('\\')
                elif e=='/': out.append('/')
                elif e=='b': out.append('\b')
                elif e=='f': out.append('\f')
                elif e=='n': out.append('\n')
                elif e=='r': out.append('\r')
                elif e=='t': out.append('\t')
                elif e=='u':
                    cp=self._parse_u_escape()
                    # handle surrogate pair
                    if 0xD800 <= cp <= 0xDBFF:
                        # expect low surrogate
                        save=self.i
                        if self.i+1<self.n and self.s[self.i]=='\\' and self.s[self.i+1]=='u':
                            self.i+=2
                            try:
                                cp2=self._parse_u_escape()
                            except SerdeErrorRaw:
                                raise
                            if 0xDC00 <= cp2 <= 0xDFFF:
                                out.append(chr(0x10000+((cp-0xD800)<<10)+(cp2-0xDC00)))
                            else:
                                self.err("lone leading surrogate in hex escape", self.i)
                        else:
                            self.err("lone leading surrogate in hex escape", self.i)
                    elif 0xDC00 <= cp <= 0xDFFF:
                        # Rust serde: lone leading surrogate message is also used for trailing? approximation
                        self.err("lone leading surrogate in hex escape", self.i)
                    else:
                        out.append(chr(cp))
                else:
                    self.err("invalid escape", self.i)
            elif ord(c) < 0x20:
                self.i+=1
                self.err("control character (\\u0000-\\u001F) found while parsing a string", self.i)
            else:
                out.append(c); self.i+=1
    def _parse_u_escape(self):
        if self.i+4>self.n:
            # advance to end
            self.i=self.n
            self.err("EOF while parsing a string", self.i)
        h=self.s[self.i:self.i+4]
        for ch in h:
            if ch not in '0123456789abcdefABCDEF':
                self.i+= (h.index(ch)+1)
                self.err("invalid escape", self.i)
        self.i+=4
        return int(h,16)
    def parse_array(self):
        st=self.i
        self.i+=1
        items=[]
        self.skip_ws()
        if self.i>=self.n:
            self.err("EOF while parsing a list", self.i)
        if self.peek()==']':
            self.i+=1
            return JNode('array',items,st,self.i,items=items)
        while True:
            # EOF check handled in parse_value but serde gives list EOF after comma etc.
            self.skip_ws()
            if self.i>=self.n:
                self.err("EOF while parsing a list", self.i)
            item=self.parse_value()
            items.append(item)
            self.skip_ws()
            if self.i>=self.n:
                self.err("EOF while parsing a list", self.i)
            c=self.s[self.i]
            if c==',':
                self.i+=1
                continue
            elif c==']':
                self.i+=1
                return JNode('array',items,st,self.i,items=items)
            else:
                self.i+=1
                self.err("expected `,` or `]`", self.i)
    def parse_object(self):
        st=self.i
        self.i+=1
        entries=[]
        self.skip_ws()
        if self.i>=self.n:
            self.err("EOF while parsing an object", self.i)
        if self.peek()=='}':
            self.i+=1
            return JNode('object',None,st,self.i,entries=entries)
        while True:
            self.skip_ws()
            if self.i>=self.n:
                self.err("EOF while parsing an object", self.i)
            if self.s[self.i]!='"':
                self.i+=1
                self.err("key must be a string", self.i)
            kst=self.i
            key=self.parse_string()
            knode=JNode('string',key,kst,self.i)
            self.skip_ws()
            if self.i>=self.n:
                self.err("EOF while parsing an object", self.i)
            if self.s[self.i]!=':':
                self.i+=1
                self.err("expected `:`", self.i)
            self.i+=1
            val=self.parse_value()
            entries.append((key,knode,val))
            self.skip_ws()
            if self.i>=self.n:
                self.err("EOF while parsing an object", self.i)
            c=self.s[self.i]
            if c==',':
                self.i+=1
                continue
            elif c=='}':
                self.i+=1
                return JNode('object',None,st,self.i,entries=entries)
            else:
                self.i+=1
                self.err("expected `,` or `}`", self.i)

def _unexpected(node):
    if node.kind=='null':
        return "null"
    if node.kind=='bool':
        return f"boolean `{'true' if node.value else 'false'}`"
    if node.kind=='int':
        return f"integer `{node.value}`"
    if node.kind=='float':
        # Rust f64 display approx: use Python repr but strip exponent format differences roughly
        v=node.value
        # serde Unexpected::Float uses {} formatting
        if v==int(v) and abs(v)<1e16:
            s=str(int(v))
            # raw had fraction though: Rust float 1.0 displays "1"? In Unexpected it may show "1"? uncommon
            # Use raw-normalised: Python str(v) gives '1.0'; Rust {} for 1.0 gives '1'
            s_rust = ('%f' % v)
            # Actually Rust Display for f64: prints without trailing .0; mimic by Python repr trimming?
            # We'll use: if float is integral, str(int(v)); else repr with removal etc.
            disp=s
        else:
            disp=repr(v)
            # Python uses 'e' notation for large/small; Rust Display does not use exponent.
            # Convert exponent notation to plain decimal if present
            if 'e' in disp or 'E' in disp:
                disp=format(v,'f').rstrip('0').rstrip('.') if '.' in format(v,'f') else format(v,'f')
        return f"floating point `{disp}`"
    if node.kind=='string':
        return f'string "{node.value}"'
    if node.kind=='array':
        return "sequence"
    if node.kind=='object':
        return "map"
    return node.kind

class _ContractConv:
    def __init__(self,text):
        self.text=text
    def serde_err(self,msg,index):
        raise SerdeErrorRaw(_serde_msg_at(self.text,msg,index))
    def invalid_type(self,node,expected,index):
        self.serde_err(f"invalid type: {_unexpected(node)}, expected {expected}", index)

    # ---- Param conversion ----
    def convert_param(self,node,ctx_index,is_component=False,is_event=False):
        expected = "a valid tuple parameter spec" if is_component else "a valid event parameter spec"
        if node.kind!='object':
            self.invalid_type(node,expected,ctx_index)
        name=None; kind_pt=None; kind_seen=False; components=None; components_seen=False; indexed=False
        seen=set()
        for key,knode,val in node.entries:
            if key=="name":
                if "name" in seen:
                    self.serde_err("duplicate field `name`", ctx_index)
                seen.add("name")
                if val.kind!='string':
                    self.invalid_type(val,"a string",ctx_index)
                name=val.value
            elif key=="type":
                if "kind" in seen:
                    self.serde_err("duplicate field `kind`", ctx_index)
                seen.add("kind")
                if val.kind!='string':
                    self.invalid_type(val,"a correct name of abi-encodable parameter type",ctx_index)
                try:
                    kind_pt=read_param_type(val.value)
                except ReaderError as e:
                    if e.kind=='parse_int':
                        content=f"ParseInt(ParseIntError {{ kind: {e.int_kind} }})"
                        self.serde_err(content, ctx_index)
                    elif e.kind=='invalid_name':
                        content=f"InvalidName({rust_debug_string(e.payload)})"
                        self.serde_err(content, ctx_index)
                    else:
                        raise
                kind_seen=True
            elif key=="components":
                if "components" in seen:
                    self.serde_err("duplicate field `components`", ctx_index)
                seen.add("components")
                if val.kind!='array':
                    self.invalid_type(val,"a sequence",ctx_index)
                comps=[]
                for item in val.items:
                    cp=self.convert_param(item,ctx_index,is_component=True,is_event=False)
                    comps.append(cp)
                components=comps; components_seen=True
            elif key=="indexed" and is_event:
                if "indexed" in seen:
                    self.serde_err("duplicate field `indexed`", ctx_index)
                seen.add("indexed")
                if val.kind!='bool':
                    self.invalid_type(val,"a boolean",ctx_index)
                indexed=val.value
            else:
                # unrecognised field: ignored
                pass
        if name is None:
            self.serde_err("missing field `name`", ctx_index)
        if not kind_seen:
            self.serde_err("missing field `kind`", ctx_index)
        if pt_contains_tuple_through_arrays(kind_pt):
            if not components_seen:
                self.serde_err("missing field `components`", ctx_index)
            comp_types=[c[1] for c in components]
            kind_pt=pt_append_components(kind_pt, comp_types)
        if is_event:
            return (name,kind_pt,indexed)
        return (name,kind_pt)

    def convert_param_list(self,node,ctx_index,is_event=False):
        if node.kind!='array':
            self.invalid_type(node,"a sequence",ctx_index)
        out=[]
        for item in node.items:
            out.append(self.convert_param(item,ctx_index,is_component=False,is_event=is_event))
        return out

    def convert_statemut(self,node,ctx_index):
        variants=["pure","view","nonpayable","payable"]
        if node.kind=='string':
            if node.value not in variants:
                self.serde_err(f"unknown variant `{node.value}`, expected one of `pure`, `view`, `nonpayable`, `payable`", ctx_index)
            return node.value
        elif node.kind=='object':
            if len(node.entries)!=1:
                self.serde_err("invalid value: map, expected map with a single key", ctx_index)
            k=node.entries[0][0]; v=node.entries[0][2]
            if k not in variants:
                self.serde_err(f"unknown variant `{k}`, expected one of `pure`, `view`, `nonpayable`, `payable`", ctx_index)
            # unit value
            if v.kind=='null':
                return k
            if v.kind=='object' and len(v.entries)==0:
                return k
            self.invalid_type(v,"unit",ctx_index)
        else:
            self.invalid_type(node,"string or map",ctx_index)

    def convert_operation(self,node):
        ctx_index=node.end
        if node.kind!='object':
            # position for primitives: node end (numbers may need +1 for following delimiter peek, approximated in caller?)
            self.invalid_type(node,"internally tagged enum Operation", ctx_index)
        # find tag
        tag=None; tag_seen=False
        for key,knode,val in node.entries:
            if key=="type":
                if tag_seen:
                    self.serde_err("duplicate field `type`", ctx_index)
                tag_seen=True
                if val.kind!='string':
                    # expected variant identifier, position closer to value end
                    self.invalid_type(val,"variant identifier", val.end)
                tag=val.value
                break
        if not tag_seen:
            self.serde_err("missing field `type`", ctx_index)
        variants=["constructor","function","event","error","fallback","receive"]
        if tag not in variants:
            # position approximately after tag string token
            # find its node end
            tag_end=ctx_index
            for key,knode,val in node.entries:
                if key=="type":
                    tag_end=val.end; break
            self.serde_err(f"unknown variant `{tag}`, expected one of `constructor`, `function`, `event`, `error`, `fallback`, `receive`", tag_end)
        # Helper to process fields
        def process(recognized):
            # recognized: dict json_key -> (internal_name, converter val->value)
            result={}
            seen=set()
            for key,knode,val in node.entries:
                if key=="type":
                    if "type" in seen:
                        self.serde_err("duplicate field `type`", ctx_index)
                    seen.add("type")
                    continue
                if key not in recognized:
                    continue
                internal,conv=recognized[key]
                if internal in seen:
                    self.serde_err(f"duplicate field `{internal}`", ctx_index)
                seen.add(internal)
                result[internal]=conv(val)
            return result
        def need_string(val):
            if val.kind!='string': self.invalid_type(val,"a string",ctx_index)
            return val.value
        def need_bool(val):
            if val.kind!='bool': self.invalid_type(val,"a boolean",ctx_index)
            return val.value
        def opt_bool(val):
            if val.kind=='null': return None
            if val.kind!='bool': self.invalid_type(val,"a boolean",ctx_index)
            return val.value
        if tag=="constructor":
            r=process({"inputs":("inputs", lambda v: self.convert_param_list(v,ctx_index,False))})
            if "inputs" not in r: self.serde_err("missing field `inputs`", ctx_index)
            return ('constructor', r["inputs"])
        if tag=="function":
            r=process({
                "name":("name", need_string),
                "inputs":("inputs", lambda v: self.convert_param_list(v,ctx_index,False)),
                "outputs":("outputs", lambda v: self.convert_param_list(v,ctx_index,False)),
                "constant":("constant", opt_bool),
                "stateMutability":("stateMutability", lambda v: self.convert_statemut(v,ctx_index)),
            })
            for f in ["name","inputs","outputs"]:
                if f not in r: self.serde_err(f"missing field `{f}`", ctx_index)
            return ('function', r["name"], r["inputs"], r["outputs"])
        if tag=="event":
            r=process({
                "name":("name", need_string),
                "inputs":("inputs", lambda v: self.convert_param_list(v,ctx_index,True)),
                "anonymous":("anonymous", need_bool),
            })
            for f in ["name","inputs","anonymous"]:
                if f not in r: self.serde_err(f"missing field `{f}`", ctx_index)
            return ('event', r["name"], r["inputs"], r["anonymous"])
        if tag=="error":
            r=process({
                "name":("name", need_string),
                "inputs":("inputs", lambda v: self.convert_param_list(v,ctx_index,False)),
            })
            for f in ["name","inputs"]:
                if f not in r: self.serde_err(f"missing field `{f}`", ctx_index)
            return ('error', r["name"], r["inputs"])
        if tag in ("fallback","receive"):
            # no recognised fields, but need duplicate 'type' check which process does if called
            r=process({})
            return (tag,)
        raise AssertionError(tag)

class Contract:
    def __init__(self,operations):
        self.functions=[]
        self.events=[]
        self.constructor=None
        for op in operations:
            if op[0]=='function':
                # op: (function, name, inputs[(name,pt)], outputs)
                self.functions.append(op)
            elif op[0]=='event':
                self.events.append(op)
            elif op[0]=='constructor':
                self.constructor=op

def load_contract_from_text(text):
    parser=JsonParser(text)
    conv=_ContractConv(text)
    parser.skip_ws()
    if parser.i>=parser.n:
        parser.err("EOF while parsing a value", parser.i)
    if parser.peek()!='[':
        # invalid type handling
        if parser.peek()=='{':
            parser.i+=1
            # serde peeks one more char for map start
            idx=parser.i+1 if parser.i<parser.n else parser.i
            conv.serde_err("invalid type: map, expected valid abi spec file", idx)
        node=parser.parse_value()
        conv.invalid_type(node,"valid abi spec file", node.end)
    # parse array manually to interleave conversion
    parser.i+=1  # '['
    operations=[]
    parser.skip_ws()
    if parser.i>=parser.n:
        parser.err("EOF while parsing a list", parser.i)
    if parser.peek()==']':
        parser.i+=1
    else:
        while True:
            parser.skip_ws()
            if parser.i>=parser.n:
                parser.err("EOF while parsing a list", parser.i)
            # For object operations, unknown variant / invalid tag type errors
            # should take precedence over syntax errors later in the object.
            # We approximate by simply parsing the whole value.
            node=parser.parse_value()
            # Adjust primitive operation node position: numbers/bools etc in serde
            # are reported after peeking delimiter; keep node.end for simplicity,
            # but for int/float nodes, bump by one if next char exists (delimiter)
            orig_end=node.end
            if node.kind in ('int','float','bool','null'):
                # serde reads delimiter peek for numbers/literals? For '[1,2]'
                # integer `1` was reported at column 3 (node.end=2 -> +1)
                # For string node end is already after closing quote and reported exactly.
                if node.kind in ('int','float'):
                    node.end = orig_end+1 if orig_end<parser.n else orig_end
            op=conv.convert_operation(node)
            operations.append(op)
            parser.skip_ws()
            if parser.i>=parser.n:
                parser.err("EOF while parsing a list", parser.i)
            c=parser.s[parser.i]
            if c==',':
                parser.i+=1
                continue
            elif c==']':
                parser.i+=1
                break
            else:
                parser.i+=1
                parser.err("expected `,` or `]`", parser.i)
    parser.skip_ws()
    if parser.i<parser.n:
        parser.i+=1
        parser.err("trailing characters", parser.i)
    return Contract(operations)

def load_contract(path):
    # File open semantics
    # Directory: serde reading error
    try:
        is_dir=os.path.isdir(path)
    except Exception:
        is_dir=False
    if is_dir:
        raise err_serialization("Is a directory (os error 21)")
    try:
        with open(path,'rb') as f:
            data=f.read()
    except OSError as e:
        # plain io error
        msg=os.strerror(e.errno) if e.errno else str(e)
        # Rust io error display capitalises first letter as in strerror
        raise AppError(f"{msg} (os error {e.errno})") if e.errno else AppError(msg)
    try:
        text=data.decode('utf-8')
    except UnicodeDecodeError as e:
        # approximation of serde_json invalid utf-8 error
        # serde_json error messages for invalid UTF-8 depend on context.
        # Use a generic message at the position of the bad byte.
        # Determine line/col in bytes up to error start (decoded leniently)
        prefix=data[:e.start].decode('utf-8',errors='ignore')
        idx=len(prefix)
        msg=_serde_msg_at(prefix, "invalid unicode code point", idx)
        raise err_serialization(msg)
    try:
        return load_contract_from_text(text)
    except SerdeErrorRaw as e:
        raise err_serialization(e.content)

# Function / event helpers
def function_short_signature(fn):
    _tag,name,inputs,outputs=fn
    return f"{name}(" + ",".join(pt_display(p[1]) for p in inputs) + ")"
def function_long_signature(fn):
    _tag,name,inputs,outputs=fn
    short=function_short_signature(fn)
    if len(outputs)==0:
        return short
    return short + ":(" + ",".join(pt_display(p[1]) for p in outputs) + ")"
def function_selector(fn):
    return keccak256(function_short_signature(fn).encode('utf-8'))[:4]
def event_signature_str(ev):
    _tag,name,inputs,anon=ev
    return f"{name}(" + ",".join(pt_display(p[1]) for p in inputs) + ")"
def event_signature_hash(ev):
    return keccak256(event_signature_str(ev).encode('utf-8'))

def get_function(contract, name_or_sig):
    name=name_or_sig.split('(',1)[0] if '(' in name_or_sig else name_or_sig
    cand=[f for f in contract.functions if f[1]==name]
    if len(cand)==0:
        raise err_invalid_name(name)
    if '(' not in name_or_sig:
        if len(cand)>1:
            raise AppError(f"More than one function found for name `{name}`, try providing the full signature")
        return cand[0]
    for f in cand:
        if function_long_signature(f)==name_or_sig:
            return f
    raise AppError(f"invalid function signature `{name_or_sig}`")

def get_event(contract, name_or_sig):
    name=name_or_sig.split('(',1)[0] if '(' in name_or_sig else name_or_sig
    cand=[e for e in contract.events if e[1]==name]
    if len(cand)==0:
        raise err_invalid_name(name)
    if '(' not in name_or_sig:
        if len(cand)>1:
            raise AppError(f"More than one function found for name `{name}`, try providing the full signature")
        return cand[0]
    h=keccak256(name_or_sig.replace(' ','').encode('utf-8'))
    for e in cand:
        if event_signature_hash(e)==h:
            return e
    hx=h.hex()
    raise AppError(f"Invalid signature `0x{hx[:4]}\u2026{hx[-4:]}`")

