# ---------------------------------------------------------------------------
# CLI (clap v2 emulation)
# ---------------------------------------------------------------------------
class ExitProgram(Exception):
    def __init__(self, code, out="", err=""):
        self.code=code; self.out=out; self.err=err

BIN_NAME="executable"

NODE_PATHS={
    'root': [],
    'encode': ['encode'],
    'decode': ['decode'],
    'encode_function': ['encode','function'],
    'encode_params': ['encode','params'],
    'decode_function': ['decode','function'],
    'decode_params': ['decode','params'],
    'decode_log': ['decode','log'],
}
NODE_CHILDREN={
    'root': {'encode':'encode','decode':'decode'},
    'encode': {'function':'encode_function','params':'encode_params'},
    'decode': {'function':'decode_function','params':'decode_params','log':'decode_log'},
}
NODE_SUBCOMMAND_CANDIDATES={
    'root': ['encode','decode','help'],
    'encode': ['function','params','help'],
    'decode': ['function','params','log','help'],
}
NODE_REQUIRED_POS={
    'encode_function': ['<abi-path>','<function-name-or-signature>'],
    'encode_params': [],
    'decode_function': ['<abi-path>','<function-name-or-signature>','<data>'],
    'decode_params': ['<data>'],
    'decode_log': ['<abi-path>','<event-name-or-signature>','<data>'],
}
NODE_USER_ARGS={
    'encode_function': [('lenient','--lenient'),('params','-p <params>...')],
    'encode_params': [('lenient','--lenient'),('type-or-param','-v <type-or-param> <type-or-param>')],
    'decode_function': [],
    'decode_params': [('type','-t <type>...')],
    'decode_log': [('topic','-l <topic>...')],
}
NODE_FULL_USAGE={
    'root': '{bin} <SUBCOMMAND>',
    'encode': '{bin} encode <SUBCOMMAND>',
    'decode': '{bin} decode <SUBCOMMAND>',
    'encode_function': '{bin} encode function [FLAGS] [OPTIONS] <abi-path> <function-name-or-signature>',
    'encode_params': '{bin} encode params [FLAGS] [OPTIONS]',
    'decode_function': '{bin} decode function <abi-path> <function-name-or-signature> <data>',
    'decode_params': '{bin} decode params [OPTIONS] <data>',
    'decode_log': '{bin} decode log [OPTIONS] <abi-path> <event-name-or-signature> <data>',
}
NODE_HELP_KEY={
    'root':'root_short','encode':'encode_short','decode':'decode_short',
    'encode_function':'encode_function_short','encode_params':'encode_params_short',
    'decode_function':'decode_function_short','decode_params':'decode_params_short','decode_log':'decode_log_short',
}

def node_prefix(node):
    path=NODE_PATHS[node]
    return BIN_NAME + (" "+" ".join(path) if path else "")

def node_help(node, long=False):
    if long and node=='encode_params':
        tpl=HELP_TEMPLATES['encode_params_long']
    else:
        tpl=HELP_TEMPLATES[NODE_HELP_KEY[node]]
    return tpl.replace("{bin}", BIN_NAME)

def node_version(node):
    if node=='root':
        return "ethabi-cli 18.0.0\n"
    path="-".join(NODE_PATHS[node])
    return f"{BIN_NAME}-{path} 18.0.0\n"

def usage_for_error(node, used=None, suggested=None):
    used=set(used or [])
    if suggested:
        used.add(suggested)
    if not used:
        return NODE_FULL_USAGE[node].replace("{bin}",BIN_NAME)
    parts=[node_prefix(node)]
    parts.extend(NODE_REQUIRED_POS.get(node,[]))
    if 'help' in used:
        parts.append('--help')
    for uid,label in NODE_USER_ARGS.get(node,[]):
        if uid in used:
            parts.append(label)
    if 'version' in used:
        parts.append('--version')
    return " ".join(parts)

def clap_error_text(msg, usage):
    return f"error: {msg}\n\nUSAGE:\n    {usage}\n\nFor more information try --help\n"

def raise_unknown_arg(node, arg_display, used=None, suggested=None, suggestion_name=None):
    usage=usage_for_error(node, used, suggested)
    msg=f"Found argument '{arg_display}' which wasn't expected, or isn't valid in this context"
    if suggestion_name:
        msg+=f"\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{suggestion_name}\x1b[0m?"
    raise ExitProgram(1, err=clap_error_text(msg, usage))

def raise_invalid_subcommand(node, token, suggestion):
    usage=NODE_FULL_USAGE[node].replace("{bin}",BIN_NAME)
    prefix=node_prefix(node)
    text=(f"error: The subcommand '{token}' wasn't recognized\n"
          f"\tDid you mean '{suggestion}'?\n\n"
          f"If you believe you received this message in error, try re-running with '{prefix} -- {token}'\n\n"
          f"USAGE:\n    {usage}\n\nFor more information try --help\n")
    raise ExitProgram(1, err=text)

def raise_help_unrecognized(comp):
    text=(f"error: The subcommand '{comp}' wasn't recognized\n\n"
          f"USAGE:\n\t{BIN_NAME} help <subcommands>...\n\nFor more information try --help\n")
    raise ExitProgram(1, err=text)

# Jaro-Winkler
def _jaro(s1,s2):
    if s1==s2:
        return 1.0
    len1=len(s1); len2=len(s2)
    if len1==0 or len2==0:
        return 0.0
    match_distance=max(len1,len2)//2-1
    if match_distance<0:
        match_distance=0
    s1_matches=[False]*len1; s2_matches=[False]*len2
    matches=0
    for i in range(len1):
        start=max(0,i-match_distance); end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if not s2_matches[j] and s1[i]==s2[j]:
                s1_matches[i]=True; s2_matches[j]=True; matches+=1; break
    if matches==0:
        return 0.0
    k=0; transpositions=0
    for i in range(len1):
        if s1_matches[i]:
            while not s2_matches[k]:
                k+=1
            if s1[i]!=s2[k]:
                transpositions+=1
            k+=1
    transpositions//=2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches)/3.0

def _jaro_winkler(s1,s2):
    j=_jaro(s1,s2)
    if j>0.7:
        prefix=0
        for a,b in zip(s1,s2):
            if a==b and prefix<4:
                prefix+=1
            else:
                break
        j+=prefix*0.1*(1-j)
    return j

def did_you_mean(value, candidates):
    best=None; best_conf=0.8  # strictly greater than 0.8 required
    for cand in candidates:
        conf=_jaro_winkler(value,cand)
        if conf>best_conf:
            best_conf=conf; best=cand
    return best

class ArgCursor:
    def __init__(self,tokens):
        self.tokens=tokens
        self.i=0
    def has_next(self):
        return self.i < len(self.tokens)
    def _validate(self, tok):
        raw=os.fsencode(tok)
        try:
            raw.decode('utf-8')
        except UnicodeDecodeError:
            panic_env_args(raw)
        return tok
    def peek(self):
        # Peek without consuming: in clap this still fetches the arg string, so
        # invalid UTF-8 would panic when it is fetched.  Our call sites use
        # peek only when actively considering the next token.
        if not self.has_next(): return None
        return self._validate(self.tokens[self.i])
    def next(self):
        if not self.has_next(): return None
        tok=self._validate(self.tokens[self.i])
        self.i+=1
        return tok
    def remaining_raw_count(self):
        return len(self.tokens)-self.i

def is_flag_like(tok):
    return tok is not None and len(tok)>1 and tok.startswith('-')

def print_exit(text, code=0, err=False):
    if err:
        raise ExitProgram(code, err=text)
    raise ExitProgram(code, out=text)

def help_node_text(parent_node):
    path=NODE_PATHS[parent_node]
    title=BIN_NAME + ("-"+"-".join(path) if path else "") + "-help \n"
    usage=BIN_NAME + (" "+" ".join(path) if path else "") + " help [subcommand]...\n"
    return (title+
            "Prints this message or the help of the given subcommand(s)\n\n"
            "USAGE:\n    "+usage+"\n"
            "ARGS:\n    <subcommand>...    The subcommand whose help message to display\n")

def handle_help_subcommand(parent_node, cursor):
    # Collect remaining args, validating sequentially as we process them.
    args=[]
    while cursor.has_next():
        args.append(cursor.next())
    if len(args)==0:
        print_exit(node_help(parent_node,long=False),0)
    if args[0]=='help':
        if len(args)==1:
            print_exit(help_node_text(parent_node),0)
        else:
            raise_help_unrecognized(args[1])
    node=parent_node
    for comp in args:
        children=NODE_CHILDREN.get(node,{})
        if comp not in children:
            raise_help_unrecognized(comp)
        node=children[comp]
    print_exit(node_help(node,long=False),0)

def long_flag_candidates(node):
    cand=['help','version']
    if node in ('encode_function','encode_params'):
        cand.append('lenient')
    return cand

def long_suggestion(node, name):
    sugg=did_you_mean(name, long_flag_candidates(node))
    return sugg

def handle_long_token(node, cursor, token, used, lenient_ref=None):
    # returns ('lenient',True) if lenient flagged, else None; help/version exit
    body=token[2:]
    name=body.split('=',1)[0]
    if name=='help':
        print_exit(node_help(node,long=True),0)
    if name=='version':
        print_exit(node_version(node),0)
    if name=='lenient' and node in ('encode_function','encode_params'):
        used.add('lenient')
        return True
    sugg=long_suggestion(node,name)
    sid=sugg if sugg in ('help','version','lenient') else None
    raise_unknown_arg(node, f"--{name}", used=used, suggested=sid, suggestion_name=sugg)

def parse_subcommand_node(node, cursor):
    # Parses flags before subcommand, returns child node key; help handled internally
    used=set()
    after_dd=False
    while True:
        if not cursor.has_next():
            # print help to stderr, exit 1
            raise ExitProgram(1, err=node_help(node,long=False))
        tok=cursor.peek()
        if not after_dd and tok=='--':
            cursor.next(); after_dd=True; continue
        if not after_dd and is_flag_like(tok):
            token=cursor.next()
            if token.startswith('--'):
                handle_long_token(node,cursor,token,used)
                continue
            else:
                # short cluster: only h,V are flags
                j=1
                while j < len(token):
                    ch=token[j]
                    if ch=='h':
                        print_exit(node_help(node,long=False),0)
                    elif ch=='V':
                        print_exit(node_version(node),0)
                    else:
                        raise_unknown_arg(node, f"-{ch}", used=used)
                    j+=1
                continue
        # positional / subcommand
        token=cursor.next()
        if not after_dd and token=='help':
            handle_help_subcommand(node,cursor)
        children=NODE_CHILDREN.get(node,{})
        if not after_dd and token in children:
            return children[token]
        # unknown subcommand / argument
        sugg=did_you_mean(token, NODE_SUBCOMMAND_CANDIDATES.get(node,[]))
        if sugg:
            raise_invalid_subcommand(node, token, sugg)
        else:
            raise_unknown_arg(node, token, used=used)

class LeafResult:
    def __init__(self):
        self.positionals=[]
        self.lenient=False
        self.params=[]
        self.types=[]
        self.topics=[]
        self.type_or_params=[]

def parse_leaf(node, cursor):
    res=LeafResult()
    required=NODE_REQUIRED_POS.get(node,[])
    used=set()
    # option presence/count tracking
    opt_present=set()
    after_dd=False
    # helpers for option labels/ids
    def opt_id_for_char(ch):
        if node=='encode_params' and ch=='v': return 'type-or-param'
        if node=='encode_function' and ch=='p': return 'params'
        if node=='decode_params' and ch=='t': return 'type'
        if node=='decode_log' and ch=='l': return 'topic'
        return None
    def add_opt_value(oid, value):
        if oid=='params': res.params.append(value)
        elif oid=='type': res.types.append(value)
        elif oid=='topic': res.topics.append(value)
        elif oid=='type-or-param': res.type_or_params.append(value)
    while cursor.has_next():
        tok=cursor.peek()
        if not after_dd and tok=='--':
            cursor.next(); after_dd=True; continue
        if not after_dd and is_flag_like(tok):
            token=cursor.next()
            if token.startswith('--'):
                r=handle_long_token(node,cursor,token,used)
                if r:
                    res.lenient=True
                continue
            # short cluster
            j=1
            while j < len(token):
                ch=token[j]
                if ch=='h':
                    print_exit(node_help(node,long=False),0)
                elif ch=='V':
                    print_exit(node_version(node),0)
                elif ch=='l' and node in ('encode_function','encode_params'):
                    used.add('lenient'); res.lenient=True; j+=1; continue
                else:
                    oid=opt_id_for_char(ch)
                    if oid is None:
                        raise_unknown_arg(node, f"-{ch}", used=used)
                    # option handling; rest of token after ch
                    used.add(oid); opt_present.add(oid)
                    rest=token[j+1:]
                    if oid=='type-or-param':
                        if rest.startswith('='):
                            add_opt_value(oid, rest[1:])
                        elif rest!="":
                            add_opt_value(oid, rest)
                            # consume one more token unconditionally as second value
                            if cursor.has_next():
                                add_opt_value(oid, cursor.next())
                        else:
                            # consume up to two tokens unconditionally
                            if cursor.has_next():
                                add_opt_value(oid, cursor.next())
                                if cursor.has_next():
                                    add_opt_value(oid, cursor.next())
                    else:
                        if rest.startswith('='):
                            add_opt_value(oid, rest[1:])
                        elif rest!="":
                            add_opt_value(oid, rest)
                        else:
                            # separated: consume next token if not flag-like
                            if cursor.has_next():
                                nt=cursor.peek()
                                if nt=='-' or not is_flag_like(nt):
                                    # Note: a token '--' is flag-like, so not consumed
                                    add_opt_value(oid, cursor.next())
                    break  # cluster ends after option
            continue
        else:
            token=cursor.next()
            if len(res.positionals) < len(required):
                res.positionals.append(token)
            else:
                raise_unknown_arg(node, token, used=used)
    # end validations
    if len(res.positionals) < len(required):
        missing=required[len(res.positionals):]
        usage=usage_for_error(node, used)
        msg="The following required arguments were not provided:\n" + "\n".join(f"    {m}" for m in missing)
        raise ExitProgram(1, err=clap_error_text(msg, usage))
    # option missing values
    # -v special
    if 'type-or-param' in opt_present:
        total=len(res.type_or_params)
        if total==0:
            usage=usage_for_error(node, used)
            msg="The argument '-v <type-or-param> <type-or-param>' requires a value but none was supplied"
            raise ExitProgram(1, err=clap_error_text(msg, usage))
        if total%2==1:
            usage=usage_for_error(node, used)
            msg="The argument '-v <type-or-param> <type-or-param>' requires 2 values, but 1 was provided"
            raise ExitProgram(1, err=clap_error_text(msg, usage))
    # one-value options
    for oid,label,vals in [
        ('params',"-p <params>...",res.params),
        ('type',"-t <type>...",res.types),
        ('topic',"-l <topic>...",res.topics),
    ]:
        if oid in opt_present and len(vals)==0:
            usage=usage_for_error(node, used)
            msg=f"The argument '{label}' requires a value but none was supplied"
            raise ExitProgram(1, err=clap_error_text(msg, usage))
    return res

# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------
def output_text(s):
    raise ExitProgram(0, out=s)

def cmd_encode_params(res):
    pairs=[]
    vals=res.type_or_params
    for i in range(0,len(vals),2):
        pairs.append((vals[i],vals[i+1]))
    types=[read_param_type_cli(t) for t,_v in pairs]
    toks=[]
    tz=Tokenizer(res.lenient)
    for pt,(_t,v) in zip(types,pairs):
        toks.append(tz.tokenize(pt,v))
    data=encode_tokens(toks)
    output_text(data.hex()+"\n")

def cmd_encode_function(res):
    abi_path, fn_name = res.positionals[0], res.positionals[1]
    contract=load_contract(abi_path)
    fn=get_function(contract, fn_name)
    inputs=fn[2]
    tz=Tokenizer(res.lenient)
    toks=[]
    for (_n,pt), v in zip(inputs, res.params):
        toks.append(tz.tokenize(pt,v))
    if len(toks)!=len(inputs):
        raise err_invalid_data()
    data=function_selector(fn)+encode_tokens(toks)
    output_text(data.hex()+"\n")

def _hex_decode_plain(s):
    try:
        return hex_decode_str(s)
    except HexParseError as e:
        raise AppError(e.msg)

def cmd_decode_params(res):
    types=[read_param_type_cli(t) for t in res.types]
    data=_hex_decode_plain(res.positionals[0])
    toks=decode_params(types, data)
    lines=[f"{pt_display(pt)} {token_display(tok)}" for pt,tok in zip(types,toks)]
    output_text("\n".join(lines)+"\n")

def cmd_decode_function(res):
    abi_path, fn_name, data_str = res.positionals
    contract=load_contract(abi_path)
    fn=get_function(contract, fn_name)
    data=_hex_decode_plain(data_str)
    out_types=[p[1] for p in fn[3]]
    toks=decode_params(out_types, data)
    lines=[f"{pt_display(pt)} {token_display(tok)}" for pt,tok in zip(out_types,toks)]
    output_text("\n".join(lines)+"\n")

def _parse_topic(s):
    t=s[2:] if s.startswith("0x") else s
    for i,ch in enumerate(t):
        if ch not in '0123456789abcdefABCDEF':
            raise AppError(f"Invalid character '{ch}' at position {i}")
    if len(t)!=64:
        raise AppError("Invalid input length")
    return bytes.fromhex(t)

def cmd_decode_log(res):
    abi_path, ev_name, data_str = res.positionals
    contract=load_contract(abi_path)
    ev=get_event(contract, ev_name)
    topics=[_parse_topic(t) for t in res.topics]
    data=_hex_decode_plain(data_str)
    _tag,_name,inputs,anon=ev
    remaining=topics
    if not anon:
        if len(topics)==0 or topics[0]!=event_signature_hash(ev):
            raise err_invalid_data()
        remaining=topics[1:]
    indexed=[p for p in inputs if p[2]]
    nonindexed=[p for p in inputs if not p[2]]
    if len(remaining) > len(indexed):
        raise err_invalid_data()
    # indexed tokens via flattened topics
    flat=b''.join(remaining)
    conv_types=[]
    for (_n,pt,_ix) in indexed:
        if pt[0] in ('address','bool','uint','int','fixedbytes'):
            conv_types.append(pt)
        else:
            conv_types.append(('fixedbytes',32))
    indexed_toks=decode_params(conv_types, flat) if conv_types else []
    data_toks=decode_params([p[1] for p in nonindexed], data)
    lines=[]
    ii=0; di=0
    for (nm,pt,ix) in inputs:
        if ix:
            tok=indexed_toks[ii]; ii+=1
        else:
            tok=data_toks[di]; di+=1
        lines.append(f"{nm} {token_display(tok)}")
    output_text("\n".join(lines)+"\n")

def cli_main():
    global BIN_NAME
    argv0=sys.argv[0] if len(sys.argv)>0 else "executable"
    base=os.path.basename(argv0)
    if base:
        BIN_NAME=base
    cursor=ArgCursor(sys.argv[1:])
    node=parse_subcommand_node('root', cursor)
    if node in ('encode','decode'):
        node2=parse_subcommand_node(node, cursor)
        node=node2
    # now leaf
    res=parse_leaf(node, cursor)
    if node=='encode_params':
        cmd_encode_params(res)
    elif node=='encode_function':
        cmd_encode_function(res)
    elif node=='decode_params':
        cmd_decode_params(res)
    elif node=='decode_function':
        cmd_decode_function(res)
    elif node=='decode_log':
        cmd_decode_log(res)
    else:
        raise AssertionError(node)

def main():
    try:
        cli_main()
    except ExitProgram as e:
        if e.out:
            try:
                sys.stdout.buffer.write(e.out.encode('utf-8'))
                sys.stdout.buffer.flush()
            except BrokenPipeError:
                pass
        if e.err:
            try:
                sys.stderr.buffer.write(e.err.encode('utf-8'))
                sys.stderr.buffer.flush()
            except BrokenPipeError:
                pass
        return e.code
    except PanicError as p:
        try:
            sys.stderr.buffer.write(p.text_bytes)
            sys.stderr.buffer.flush()
        except Exception:
            pass
        return 101
    except AppError as e:
        if e.cause is not None:
            text=f"Error: {e.message}\n\nCaused by:\n    {e.cause}\n"
        else:
            text=f"Error: {e.message}\n"
        try:
            sys.stderr.buffer.write(text.encode('utf-8'))
            sys.stderr.buffer.flush()
        except BrokenPipeError:
            pass
        return 1
    except BrokenPipeError:
        return 1
    return 0

